    &pgsql.changelog.connection-object;


     7.1.0

      È stato aggiunto il parametro mode.

  &reftitle.examples;



    Esempio di pg_select


<?php 
  $db = pg_connect('dbname=foo');
  // Questo è abbastanza sicuro, poiché viene effettuato l'escape di tutti i valori.
  // Tuttavia PostgreSQL supporta JSON/Array. Questi non sono
  // resi sicuri né dall'escape né dalle query preparate.
  $rec = pg_select($db, 'post_log', $_POST, PG_DML_ESCAPE);
  if ($rec) {
      echo "Record selezionati\n";
      var_dump($rec);
  } else {
      echo "L'utente deve aver inviato dati errati\n";
  }
?>
